def solve(a, cor=0):
    H,W=len(a),len(a[0])
    cnt=collections.Counter(x for row in a for x in row)
    dom=cnt.most_common(1)[0][0]
    # find column runs of non-dom colors with len>=2
    colruns=[]
    for c in range(W):
        col=[a[r][c] for r in range(H)]
        i=0
        while i<H:
            j=i
            while j+1<H and col[j+1]==col[j]: j+=1
            if j>i and col[i]!=dom: colruns.append((i,j,col[i]))
            i=j+1
    best=max(colruns,key=lambda x:x[1]-x[0]+1)
    b0,b1,c0=best
    linecols=[a[r][c0] for r in range(b0,b1+1)]
    first,last=linecols[0],linecols[-1]
    res=[row[:] for row in a]
    dist={}; pq=[]
    for r in range(b0,b1+1):
        dist[(r,c0)]=0; heapq.heappush(pq,(0,r,c0))
    while pq:
        d_,r,c=heapq.heappop(pq)
        if d_>dist.get((r,c),float('inf')): continue
        for nr,nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
            if 0<=nr<H and 0<=nc<W and a[nr][nc]==cor:
                nd=d_+1
                if (nr,nc) not in dist or dist[(nr,nc)]>nd:
                    dist[(nr,nc)]=nd; heapq.heappush(pq,(nd,nr,nc))
    for (r,c),dd in dist.items():
        if dd>0: res[r][c]= first if dd%2==0 else last
    return res,linecols

